"""Render ``config/watchwise.yml`` from a resolved profile.

The output is deterministic (no timestamps, stable key order), so running
``watchwise init`` twice with the same inputs produces byte-identical files
and the second run is a no-op.
"""

from __future__ import annotations

import re
from typing import Any

import yaml

from watchwise.hw.profiles import Profile

HEADER = """\
# Watchwise configuration -- generated by `watchwise init --profile {profile}`.
# {title}
#
# Safe to edit by hand: re-running `watchwise init` shows a diff and backs up
# this file before changing it. ${{VAR:-default}} values are read from the
# environment (.env), so the same file works on the host and in docker.
# Privacy: with this profile, {leaves} leaves this machine.
"""

SECTION_COMMENTS = {
    "profile": None,
    "nvr": "# Tier 1: the NVR (Frigate). Port 5000 is its internal, unauthenticated API.",
    "mqtt": "# Frigate's MQTT broker. topic_prefix must match Frigate's mqtt.topic_prefix.",
    "models": (
        "# Model endpoints. provider: stub | ollama | openai_compat | anthropic.\n"
        "# Keys are never written here: api_key_env names the variable in .env."
    ),
    "roles": (
        "# Which endpoint does which job: screener = tier-2 vision screening,\n"
        "# investigator = tier-3 tool-calling agent, chat = conversation."
    ),
    "vlm": "# Tier-2 tuning: how many frames per alert, how large, how many at once.",
    "agent": "# Tier-3 investigation budget.",
    "gate": "# The free, model-free filter in front of everything.",
    "decision": (
        "# The risk posture: below these confidences, a human decides. The first\n"
        "# card waits up to provisional_after_s (0 s while armed) for the vision\n"
        "# model, then goes out as \"Analyzing...\" and is edited with the verdict."
    ),
    "notify": (
        "# Phone alerts (Telegram). Connect a chat with `watchwise telegram link`.\n"
        "# Telegram relays card text, and the snapshot unless send_images is false."
    ),
    "memory": None,
    "duty_roster": None,
    "service": None,
}


def build_config_dict(
    profile: Profile,
    models: dict[str, dict[str, Any]],
    roles: dict[str, str],
    *,
    nvr_url: str = "${FRIGATE_URL:-http://localhost:5000}",
    mqtt_host: str = "${MQTT_HOST:-localhost}",
    topic_prefix: str = "frigate",
    mqtt_enabled: bool = True,
) -> dict[str, Any]:
    vlm = {"frames": 2, "max_image_edge": 640, "max_concurrency": 2, "timeout_s": 60}
    vlm.update(profile.tuning.get("vlm", {}))
    agent: dict[str, Any] = {"backend": profile.agent_backend or "auto"}
    agent.update({"max_iterations": 6, "max_concurrency": 2, "timeout_s": 180})
    agent.update(profile.tuning.get("agent", {}))
    return {
        "profile": profile.name,
        "nvr": {"base_url": nvr_url},
        "mqtt": {
            "enabled": mqtt_enabled,
            "host": mqtt_host,
            "port": 1883,
            "topic_prefix": topic_prefix,
            "screen_on": ["new", "end"],
        },
        "models": {name: _clean(spec) for name, spec in models.items()},
        "roles": dict(roles),
        "vlm": vlm,
        "agent": agent,
        "gate": {"dedupe_window_s": 60, "never_screen_labels": [], "always_alert_labels": []},
        "decision": {
            "screen_benign_confidence": 0.8,
            "screen_suspicious_confidence": 0.8,
            "human_fallback_confidence": 0.6,
            "auto_downgrade_confidence": 0.85,
            "provisional_after_s": 10,
            "provisional_after_armed_s": 0,
        },
        "notify": {"telegram": {"enabled": False, "chat_ids": [], "send_images": True}},
        "memory": {"db_path": "./data/watchwise.db"},
        "duty_roster": {"path": "./config/duty_roster.yml", "timezone": "UTC"},
        "service": {"host": "127.0.0.1", "port": 5055},
    }


def render_config(profile: Profile, config: dict[str, Any]) -> str:
    parts = [
        HEADER.format(
            profile=profile.name,
            title=profile.title,
            leaves=profile.leaves_machine,
        )
    ]
    for key, value in config.items():
        comment = SECTION_COMMENTS.get(key)
        block = yaml.safe_dump({key: value}, sort_keys=False, default_flow_style=False, width=100)
        parts.append(f"{comment}\n{block}" if comment else block)
    return "\n".join(parts)


def replace_top_level_block(text: str, key: str, value: Any) -> str:
    """Replace one top-level YAML mapping (or append it), leaving every other
    line of the file -- including comments -- exactly as it was."""
    block = yaml.safe_dump({key: value}, sort_keys=False, default_flow_style=False, width=100)
    lines = text.splitlines(keepends=True)
    start = next(
        (i for i, line in enumerate(lines) if re.match(rf"^{re.escape(key)}:\s*(#.*)?$", line)),
        None,
    )
    if start is None:
        prefix = text if text.endswith("\n") or not text else text + "\n"
        return prefix + ("\n" if prefix else "") + block
    end = start + 1
    while end < len(lines) and (lines[end].startswith((" ", "\t")) or not lines[end].strip()):
        end += 1
    while end > start + 1 and not lines[end - 1].strip():
        end -= 1  # keep the blank lines that separate the next section
    return "".join(lines[:start]) + block + "".join(lines[end:])


def _clean(spec: dict[str, Any]) -> dict[str, Any]:
    order = (
        "provider",
        "model",
        "base_url",
        "api_key_env",
        "effort",
        "context_window",
        "max_tokens",
        "timeout_s",
        "keep_alive",
    )
    out = {k: spec[k] for k in order if k in spec and spec[k] is not None}
    out.update({k: v for k, v in spec.items() if k not in out and v is not None})
    return out
